INSERT INTO editorial_reference_articles
(slug,title,work_type,topic,priority,summary,prompt_excerpt,body)
VALUES
('sound-design-and-mix','الصوت والموسيقى: كيف يصنع السمع معنى المشهد','movie','sound',89,
'حلّل وظيفة الحوار والمؤثرات والصمت والموسيقى والمزج، لا مجرد وجود موسيقى جميلة أو صوت مرتفع. اربط القرار السمعي بالمكان والانتباه والإيقاع والعاطفة.',
'اسأل ماذا نسمع ومتى ولماذا: هل يحدد الصوت المكان؟ هل يوجه الانتباه أو يحجب معلومة؟ هل يخلق الصمت توتراً؟ ميّز بين الموسيقى والمؤثرات والحوار، ولا تحكم على جودة المزج بلا مادة سمعية أو وصف موثوق.',
'الصوت ليس طبقة تزيينية تضاف إلى الصورة بعد اكتمالها؛ إنه جزء من بناء المكان والزمن ووجهة النظر. قد يحدد صدى الصوت حجم المكان، وقد يكشف اختلاف الضجيج انتقالاً بين بيئتين، وقد يجعل الصوت خارج الكادر العالم أوسع من حدود الصورة. لذلك لا يكفي القول إن الموسيقى مؤثرة أو إن المؤثرات قوية؛ ينبغي تحديد الوظيفة التي يؤديها الصوت داخل اللحظة.

افصل بين عناصر المسار السمعي: وضوح الحوار، والبيئة الصوتية، والمؤثرات، والموسيقى، والصمت، ثم افحص كيفية امتزاجها. هل يستطيع المتلقي تمييز الحوار من الخلفية؟ هل تتنافس الموسيقى مع الكلام؟ هل يتغير مستوى الصوت لخدمة منظور شخصية أو لإبراز حدث؟ لا يعني ارتفاع الصوت قوة التأثير، ولا يعني غياب الموسيقى فقراً؛ فقد يكون الصمت قراراً درامياً يترك مساحة للتوتر أو يجعل تفصيلاً صغيراً مسموعاً.

الموسيقى قد تكرر إحساس الصورة فتؤكده، أو تناقضه فتخلق معنى مركباً. اختبر إن كان حضورها متناسباً مع المشهد، وهل تتطور الفكرة الموسيقية مع تحول الشخصية أو الصراع. أما المؤثرات فتحتاج إلى النظر في دقتها واتساقها مع العالم، لا في كثرتها. إذا لم تتوفر مشاهدة أو مادة صوتية أو مصادر موثوقة تصف التنفيذ، فلا تدّع الحكم على جودة التسجيل أو المزج؛ اكتف بتحليل المعلومات المثبتة وصرّح بحدود التقييم.')
ON CONFLICT(slug) DO UPDATE SET title=excluded.title,work_type=excluded.work_type,topic=excluded.topic,priority=excluded.priority,summary=excluded.summary,prompt_excerpt=excluded.prompt_excerpt,body=excluded.body,version=excluded.version,active=1,updated_at=datetime('now');

INSERT INTO editorial_reference_articles
(slug,title,work_type,topic,priority,summary,prompt_excerpt,body)
VALUES
('editing-rhythm-and-continuity','المونتاج: الإيقاع والاستمرارية وبناء الانتباه','movie','editing',88,
'المونتاج ينظم علاقة اللقطات والزمن والمعلومة. قيّمه من أثر القطع والإيقاع والاستمرارية والمنظور، لا من سرعة الانتقال وحدها.',
'حلّل ما الذي يضيفه ترتيب اللقطات: هل يحافظ على وضوح المكان والزمن؟ هل يخلق إيقاعاً يخدم التوتر؟ هل يحجب معلومة بوعي أم يربك الحدث؟ لا تساوِ كثرة القطع بالحيوية.',
'المونتاج هو تنظيم للعلاقة بين الصور والأصوات والزمن، وليس مجرد وصل لقطات متتابعة. القطع يقرر متى ننتقل، وما الذي نعرفه، وأي تفصيل يحظى بانتباهنا. قد يختصر زمناً طويلاً في لحظات، أو يمدد ثانية واحدة لتصبح مشحونة، وقد يضع صورتين متجاورتين لتوليد مقارنة لا توجد في أي منهما منفردة.

ابدأ بالاستمرارية: هل يستطيع المشاهد فهم مواقع الشخصيات واتجاه الحركة والعلاقة بين الأفعال؟ كسر الاستمرارية ليس خطأ تلقائياً؛ قد يكون مقصوداً لإظهار اضطراب أو ذاكرة أو ذاتية، لكن ينبغي أن يخدم غرضاً يمكن تفسيره. ثم افحص الإيقاع: السرعة ليست قيمة بذاتها، واللقطة الطويلة ليست بطئاً بالضرورة. المهم أن يتغير شيء ذو معنى داخل الزمن الذي تمنحه اللقطة أو سلسلة اللقطات.

اسأل أيضاً كيف يوزع العمل المعلومات. هل يكشف الحدث في اللحظة المناسبة؟ هل يصنع التشويق من ترتيب المعرفة أم من إخفاء اعتباطي؟ هل تتكرر اللقطات أو المشاهد دون إضافة؟ اربط كل حكم بمثال محدد من المادة المتاحة، ولا تخترع انتقالات أو مشاهد. إذا كانت المصادر لا تتيح وصفاً موثوقاً للمونتاج، امتنع عن تقييم التنفيذ التقني واكتف بما يمكن إثباته عن بنية السرد.')
