INSERT INTO editorial_reference_articles
(slug,title,work_type,topic,priority,summary,prompt_excerpt,body)
VALUES
('documentary-evidence-and-ethics','النقد الوثائقي: الدليل والتمثيل وأخلاقيات الصورة','movie','documentary',86,
'في الوثائقي، اختبر علاقة الادعاء بالمادة التي تسنده، وسياق الشهادة والأرشيف والمونتاج وحقوق الأشخاص المصورين، دون افتراض الحياد أو التلاعب بلا دليل.',
'في نقد الوثائقي ميّز بين الحدث والشهادة والأرشيف والتعليق والمونتاج. اسأل هل يوضح العمل مصدر ادعاءاته وسياقها؟ هل يمنح الأطراف تمثيلاً منصفاً؟ لا تصف الفيلم بأنه محايد أو مضلل دون قرائن محددة.',
'لا يعني وصف العمل بأنه وثائقي أن كل ما يعرضه حقيقة مكتملة أو أن الكاميرا محايدة. الوثائقي يبني معرفة عبر اختيار موضوعات وشهادات وصور أرشيفية ومواقع تصوير وتعليق ومونتاج. لذلك يبدأ النقد بتحديد نوع الادعاء: هل يقدم العمل واقعة قابلة للتحقق، أم شهادة شخصية، أم تفسيراً، أم إعادة بناء؟ تختلف قوة كل نوع وحدوده.

افحص مصدر المادة وسياقها. من يتحدث؟ ما علاقته بالحدث؟ هل يوضح العمل متى وأين سُجلت الشهادة؟ هل يميز بين الأرشيف الأصلي وإعادة التمثيل؟ وهل يمنح الادعاءات المتنازعة سياقاً كافياً؟ لا يكفي وجود مقابلة لإثبات صحة كل ما يقال فيها، كما لا يكفي غياب طرف عن الفيلم لإثبات تعمد إسكات صوته. يجب أن يستند النقد إلى قرائن واضحة في بنية الفيلم أو مصادر مستقلة.

تتصل الأخلاقيات بطريقة تصوير الأشخاص، وحماية الفئات المعرضة للخطر، والموافقة، والخصوصية، واحتمال تحويل المعاناة إلى مشهد استعراضي. اسأل كيف تؤثر زاوية الكاميرا والمونتاج والموسيقى في تعاطف الجمهور أو حكمه، وهل يميز العمل بين المعلومة والتأويل. لا تساوِ بين وجهة نظر المخرج والتضليل، ولا بين التوازن الآلي والإنصاف؛ قد يكون عرض جميع المواقف بالتساوي مضللاً إذا كانت الأدلة غير متكافئة.

الحكم الوثائقي الأقوى يشرح كيف ينتج الفيلم معرفته، وما الذي يثبته فعلاً، وما الذي يتركه غير محسوم. لا تنسب نوايا أخلاقية إلى صناع العمل دون دليل، ولا تتحقق من الوقائع التاريخية اعتماداً على الفيلم وحده. عندما لا تتوفر مصادر مستقلة، صرّح بأن تقييم صدقية الادعاء محدود، وركز على طريقة تقديمه لا على إعلان صحته.')
